//! Every formatting must reproduce the reference's text (`tests/formats.json`, generated by the
//! maintainers from the reference implementation). Every mismatch is listed.

use p4kr_dataforge::value::{f32_text, f64_text, guid_text};

fn unhex<const N: usize>(s: &str) -> [u8; N] {
    let mut out = [0u8; N];
    assert_eq!(s.len(), N * 2, "hex length {s}");
    for (i, byte) in out.iter_mut().enumerate() {
        *byte = u8::from_str_radix(&s[i * 2..i * 2 + 2], 16).expect("hex");
    }
    out
}

fn render(kind: &str, arg: &str) -> String {
    match kind {
        "f32" => f32_text(f32::from_le_bytes(unhex(arg))),
        "f64" => f64_text(f64::from_le_bytes(unhex(arg))),
        "guid" => guid_text(&unhex(arg)),
        "i8" => arg.parse::<i8>().expect("i8").to_string(),
        "i16" => arg.parse::<i16>().expect("i16").to_string(),
        "i32" => arg.parse::<i32>().expect("i32").to_string(),
        "i64" => arg.parse::<i64>().expect("i64").to_string(),
        "u8" => arg.parse::<u8>().expect("u8").to_string(),
        "u16" => arg.parse::<u16>().expect("u16").to_string(),
        "u32" => arg.parse::<u32>().expect("u32").to_string(),
        "u64" => arg.parse::<u64>().expect("u64").to_string(),
        other => panic!("unknown type {other}"),
    }
}

#[test]
fn every_probe_matches_the_reference() {
    let rows: serde_json::Value =
        serde_json::from_str(include_str!("formats.json")).expect("formats.json");
    let rows = rows.as_array().expect("list");
    assert!(rows.len() >= 9000, "only {} probes", rows.len());
    let mut failures = Vec::new();
    for row in rows {
        let input = row["input"].as_str().expect("input");
        let want = row["text"].as_str().expect("text");
        let (kind, arg) = input.split_once(' ').expect("type value");
        let got = render(kind, arg.trim());
        if got != want {
            failures.push(format!("{input}: expected {want:?}, got {got:?}"));
        }
    }
    assert!(
        failures.is_empty(),
        "{} mismatches:\n{}",
        failures.len(),
        failures.join("\n")
    );
}
